function validate([heights, queries]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 50000) return 'heights needs 1 to 50000 values.';
  if (heights.some(h => !Number.isInteger(h) || h < 1 || h > 1000000000)) return 'Each height is a whole number from 1 to 10^9.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 50000) return 'queries needs 1 to 50000 pairs.';
  const n = heights.length;
  for (const pair of queries) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each query is a pair [a, b].';
    if (pair.some(x => !Number.isInteger(x) || x < 0 || x >= n)) return 'Each query index must be a building index.';
  }
  return null;
}

