function leftmostBuildingQueries(heights, queries) {
  const n = heights.length;
  const answer = new Array(queries.length).fill(-1);
  const waiting = Array.from({ length: n }, () => []);
  for (let q = 0; q < queries.length; q++) {
    const left = Math.min(queries[q][0], queries[q][1]);
    const right = Math.max(queries[q][0], queries[q][1]);
    if (left === right || heights[left] < heights[right]) {
      answer[q] = right;
    } else {
      waiting[right].push([q, heights[left]]);
    }
  }

  const stack = [];
  for (let i = n - 1; i >= 0; i--) {
    for (const [q, target] of waiting[i]) {
      let low = 0;
      let high = stack.length - 1;
      while (low <= high) {
        const mid = (low + high) >> 1;
        if (heights[stack[mid]] > target) {
          answer[q] = stack[mid];
          low = mid + 1;
        } else {
          high = mid - 1;
        }
      }
    }
    while (stack.length > 0 && heights[stack[stack.length - 1]] <= heights[i]) {
      stack.pop();
    }
    stack.push(i);
  }
  return answer;
}

