function leftmostBuildingQueries(heights, queries) {
  // For each query, test every building from the left and stop at the first one both can reach.
  const reach = (from, to) => from === to || (from < to && heights[from] < heights[to]);
  return queries.map(([a, b]) => {
    for (let t = 0; t < heights.length; t++) {
      if (reach(a, t) && reach(b, t)) return t;
    }
    return -1;
  });
}

