function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  const cap = large ? (rand() < 0.5 ? 1000000000 : int(2, 50)) : int(1, 6);
  const heights = Array.from({ length: n }, () => int(1, cap));
  if (rand() < 0.3) {
    // Mostly falling heights leave many queries without a meeting point.
    heights.sort((x, y) => y - x);
    for (let k = 0; k < Math.max(1, n / 20); k++) {
      const i = int(0, n - 1);
      heights[i] = int(1, cap);
    }
  }
  const count = large ? 2000 : int(1, 6);
  const queries = Array.from({ length: count }, () => [int(0, n - 1), int(0, n - 1)]);
  return [heights, queries];
}
